'use client';

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import apiClient from '@/lib/api/client';
import {
  Index,
  IndexDetail,
  IndexStats,
  IndexMappings,
  IndexSettings,
  IndexTemplate,
} from '@/types';

// ========================================
// Query Keys
// ========================================

export const indexKeys = {
  all: ['indices'] as const,
  list: (showSystem: boolean) => [...indexKeys.all, 'list', { showSystem }] as const,
  detail: (indexName: string) => [...indexKeys.all, 'detail', indexName] as const,
  stats: (indexName: string) => [...indexKeys.all, 'stats', indexName] as const,
  mappings: (indexName: string) => [...indexKeys.all, 'mappings', indexName] as const,
  settings: (indexName: string) => [...indexKeys.all, 'settings', indexName] as const,
  documents: (indexName: string, page: number, size: number) =>
    [...indexKeys.all, 'documents', indexName, { page, size }] as const,
  templates: () => [...indexKeys.all, 'templates'] as const,
  templateDetail: (name: string) => [...indexKeys.all, 'templates', name] as const,
};

// ========================================
// Index List Hooks
// ========================================

export function useIndices(showSystemIndices: boolean = false) {
  return useQuery({
    queryKey: indexKeys.list(showSystemIndices),
    queryFn: async () => {
      const response = await apiClient.get<Index[]>('/_cat/indices', {
        params: {
          format: 'json',
          h: 'health,status,index,uuid,pri,rep,docs.count,docs.deleted,store.size,pri.store.size',
          s: 'index',
        },
      });

      let indices = response.data.map((idx) => ({
        ...idx,
        docsCount: idx.docsCount || '0',
        docsDeleted: idx.docsDeleted || '0',
        storeSize: idx.storeSize || '0b',
        priStoreSize: idx.priStoreSize || '0b',
      }));

      // Filter system indices (those starting with .)
      if (!showSystemIndices) {
        indices = indices.filter((idx) => !idx.index.startsWith('.'));
      }

      return indices;
    },
  });
}

// ========================================
// Index Detail Hooks
// ========================================

export function useIndexDetail(indexName: string) {
  return useQuery({
    queryKey: indexKeys.detail(indexName),
    queryFn: async () => {
      const response = await apiClient.get<Record<string, IndexDetail>>(`/${indexName}`);
      return response.data[indexName];
    },
    enabled: !!indexName,
  });
}

export function useIndexStats(indexName: string) {
  return useQuery({
    queryKey: indexKeys.stats(indexName),
    queryFn: async () => {
      const response = await apiClient.get<{
        indices: Record<string, { total: IndexStats }>;
      }>(`/${indexName}/_stats`);
      return response.data.indices[indexName]?.total;
    },
    enabled: !!indexName,
  });
}

export function useIndexMappings(indexName: string) {
  return useQuery({
    queryKey: indexKeys.mappings(indexName),
    queryFn: async () => {
      const response = await apiClient.get<
        Record<string, { mappings: IndexMappings }>
      >(`/${indexName}/_mapping`);
      return response.data[indexName]?.mappings;
    },
    enabled: !!indexName,
  });
}

export function useIndexSettings(indexName: string) {
  return useQuery({
    queryKey: indexKeys.settings(indexName),
    queryFn: async () => {
      const response = await apiClient.get<
        Record<string, { settings: IndexSettings }>
      >(`/${indexName}/_settings`);
      return response.data[indexName]?.settings;
    },
    enabled: !!indexName,
  });
}

// ========================================
// Index Documents Hooks
// ========================================

interface SearchResponse {
  hits: {
    total: { value: number };
    hits: Array<{
      _id: string;
      _source: Record<string, unknown>;
      _index: string;
    }>;
  };
}

export function useIndexDocuments(
  indexName: string,
  page: number = 0,
  size: number = 10
) {
  return useQuery({
    queryKey: indexKeys.documents(indexName, page, size),
    queryFn: async () => {
      const response = await apiClient.post<SearchResponse>(
        `/${indexName}/_search`,
        {
          from: page * size,
          size,
          query: { match_all: {} },
        }
      );
      return {
        total: response.data.hits.total.value,
        hits: response.data.hits.hits,
      };
    },
    enabled: !!indexName,
  });
}

interface TermVectorResponse {
  term_vectors: Record<
    string,
    {
      terms: Record<
        string,
        {
          term_freq: number;
          doc_freq?: number;
          ttf?: number;
          tokens?: Array<{
            position: number;
            start_offset: number;
            end_offset: number;
          }>;
        }
      >;
    }
  >;
}

export function useIndexedTerms(indexName: string, docId: string, field: string) {
  return useQuery({
    queryKey: [...indexKeys.detail(indexName), 'terms', docId, field],
    queryFn: async () => {
      const response = await apiClient.get<TermVectorResponse>(
        `/${indexName}/_termvectors/${docId}`,
        {
          params: {
            fields: field,
            term_statistics: true,
            offsets: true,
            positions: true,
          },
        }
      );
      return response.data.term_vectors;
    },
    enabled: !!indexName && !!docId && !!field,
  });
}

// ========================================
// Index Template Hooks
// ========================================

export function useIndexTemplates() {
  return useQuery({
    queryKey: indexKeys.templates(),
    queryFn: async () => {
      const response = await apiClient.get<Record<string, IndexTemplate>>(
        '/_template/*'
      );
      return Object.entries(response.data).map(([name, template]) => ({
        ...template,
        name,
      }));
    },
  });
}

export function useIndexTemplateDetail(name: string) {
  return useQuery({
    queryKey: indexKeys.templateDetail(name),
    queryFn: async () => {
      const response = await apiClient.get<Record<string, IndexTemplate>>(
        `/_template/${name}`
      );
      return { ...response.data[name], name };
    },
    enabled: !!name,
  });
}

// ========================================
// Index Mutations
// ========================================

export function useCreateIndex() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({
      indexName,
      settings,
      mappings,
    }: {
      indexName: string;
      settings?: Record<string, unknown>;
      mappings?: IndexMappings;
    }) => {
      const response = await apiClient.put(`/${indexName}`, {
        settings,
        mappings,
      });
      return response.data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: indexKeys.all });
    },
  });
}

export function useDeleteIndex() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (indexName: string) => {
      const response = await apiClient.delete(`/${indexName}`);
      return response.data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: indexKeys.all });
    },
  });
}

export function useOpenIndex() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (indexName: string) => {
      const response = await apiClient.post(`/${indexName}/_open`);
      return response.data;
    },
    onSuccess: (_, indexName) => {
      queryClient.invalidateQueries({ queryKey: indexKeys.detail(indexName) });
      queryClient.invalidateQueries({ queryKey: indexKeys.all });
    },
  });
}

export function useCloseIndex() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (indexName: string) => {
      const response = await apiClient.post(`/${indexName}/_close`);
      return response.data;
    },
    onSuccess: (_, indexName) => {
      queryClient.invalidateQueries({ queryKey: indexKeys.detail(indexName) });
      queryClient.invalidateQueries({ queryKey: indexKeys.all });
    },
  });
}

export function useRefreshIndex() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (indexName: string) => {
      const response = await apiClient.post(`/${indexName}/_refresh`);
      return response.data;
    },
    onSuccess: (_, indexName) => {
      queryClient.invalidateQueries({ queryKey: indexKeys.stats(indexName) });
    },
  });
}

export function useFlushIndex() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (indexName: string) => {
      const response = await apiClient.post(`/${indexName}/_flush`);
      return response.data;
    },
    onSuccess: (_, indexName) => {
      queryClient.invalidateQueries({ queryKey: indexKeys.stats(indexName) });
    },
  });
}

export function useForceMergeIndex() {
  return useMutation({
    mutationFn: async ({
      indexName,
      maxNumSegments = 1,
    }: {
      indexName: string;
      maxNumSegments?: number;
    }) => {
