      queryClient.invalidateQueries({ queryKey: indexKeys.detail(indexName) });
    },
  });
}

// ========================================
// Document Mutations
// ========================================

export function useCreateDocument() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({
      indexName,
      document,
      id,
    }: {
      indexName: string;
      document: Record<string, unknown>;
      id?: string;
    }) => {
      const url = id ? `/${indexName}/_doc/${id}` : `/${indexName}/_doc`;
      const response = await apiClient.post(url, document);
      return response.data;
