}

export function useUpdateTemplate() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({
      name,
      template,
    }: {
      name: string;
      template: Omit<IndexTemplate, 'name'>;
    }) => {
      const response = await apiClient.put(`/_template/${name}`, template);
      return response.data;
    },
    onSuccess: (_, { name }) => {
      queryClient.invalidateQueries({ queryKey: indexKeys.templates() });
      queryClient.invalidateQueries({ queryKey: indexKeys.templateDetail(name) });
