'use client';

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import apiClient from '@/lib/api/client';
import { SearchTemplate, ReferenceUIConfig } from '@/types';

// ========================================
// Query Keys
// ========================================

export const searchKeys = {
  all: ['search'] as const,
  referenceUI: () => [...searchKeys.all, 'reference-ui'] as const,
  templates: () => [...searchKeys.all, 'templates'] as const,
  autocomplete: () => [...searchKeys.all, 'autocomplete'] as const,
};

// ========================================
// Queries
// ========================================

export function useReferenceUIConfig() {
  return useQuery({
    queryKey: searchKeys.referenceUI(),
    queryFn: async (): Promise<ReferenceUIConfig> => {
      const response = await apiClient.get('/_dsearch/reference');
      return response.data;
    },
  });
}

export function useSearchTemplates() {
  return useQuery({
    queryKey: searchKeys.templates(),
    queryFn: async (): Promise<SearchTemplate[]> => {
      const response = await apiClient.get('/_dsearch/reference/templates');
      return response.data || [];
    },
  });
}

// ========================================
// Mutations
// ========================================

export function useUpdateAutocompleteUrl() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (url: string) => {
      const response = await apiClient.put('/_dsearch/reference/autocomplete', { url });
      return response.data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: searchKeys.referenceUI() });
    },
  });
}

export function useCreateSearchTemplate() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (template: Omit<SearchTemplate, 'id'>) => {
      const response = await apiClient.post('/_dsearch/reference/template', template);
      return response.data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: searchKeys.templates() });
    },
  });
}

export function useUpdateSearchTemplate() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (template: SearchTemplate) => {
      const response = await apiClient.put(`/_dsearch/reference/template/${template.id}`, template);
      return response.data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: searchKeys.templates() });
    },
  });
}

export function useDeleteSearchTemplate() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (templateId: string) => {
      const response = await apiClient.delete(`/_dsearch/reference/template/${templateId}`);
      return response.data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: searchKeys.templates() });
    },
  });
}

export function useReorderSearchTemplates() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (templates: SearchTemplate[]) => {
      const response = await apiClient.put('/_dsearch/reference/templates/reorder', { templates });
      return response.data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: searchKeys.templates() });
    },
  });
}

export function useExecuteSearch() {
  return useMutation({
    mutationFn: async ({ indices, query }: { indices: string; query: string }) => {
      const indexList = indices.split(',').map(i => i.trim()).join(',');
      const response = await apiClient.post(`/${indexList}/_search`, JSON.parse(query));
      return response.data;
    },
  });
}

