"use client";

import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import apiClient from "@/lib/api/client";
import { User, Role } from "@/types";

// API Response Types
interface ElasticsearchUserResponse {
  [username: string]: {
    username: string;
    roles: string[];
    full_name?: string;
    email?: string;
    metadata?: Record<string, unknown>;
    enabled?: boolean;
  };
}

interface ElasticsearchRoleResponse {
  [roleName: string]: {
    cluster?: string[];
    indices?: Array<{
      names: string[];
      privileges: string[];
    }>;
    applications?: Array<{
      application: string;
      privileges: string[];
      resources: string[];
    }>;
    run_as?: string[];
    metadata?: Record<string, unknown>;
  };
}

interface CreateUserRequest {
  email: string;
  username: string;
  role: string;
}

interface CreateUserResponse {
  success: boolean;
  temporaryPassword: string;
}

interface UpdateUserRequest {
  username: string;
  email?: string;
  role?: string;
}

interface ResetPasswordResponse {
  success: boolean;
  temporaryPassword: string;
}

interface CreateRoleRequest {
  name: string;
  analysis: boolean;
  index: boolean;
  search: boolean;
  manage: boolean;
}

interface UpdateRoleRequest extends CreateRoleRequest {
  id: string;
}

// Transform Elasticsearch user response to our User type
function transformUsers(response: ElasticsearchUserResponse): User[] {
  return Object.entries(response).map(([username, userData]) => {
    const userRole = userData.roles?.[0] || "";
    return {
      id: username,
      username: userData.username || username,
      email: userData.email || userData.metadata?.email as string || "",
      role: userRole,
      roles: userData.roles || [],
    };
  });
}

// Transform Elasticsearch role response to our Role type
function transformRoles(response: ElasticsearchRoleResponse, usersData: User[]): Role[] {
  return Object.entries(response).map(([roleName, roleData]) => {
    // Check if role is in use by any user
    const inUse = usersData.some((user) => user.roles.includes(roleName));

    // Parse privileges from applications or cluster permissions
    const hasAnalysis = roleData.applications?.some(
      (app) => app.privileges.includes("analysis") || app.privileges.includes("all")
    ) || roleData.cluster?.includes("monitor") || false;

    const hasIndex = roleData.indices?.some(
      (idx) => idx.privileges.includes("write") || idx.privileges.includes("all")
    ) || false;

    const hasSearch = roleData.indices?.some(
      (idx) => idx.privileges.includes("read") || idx.privileges.includes("all")
    ) || true; // Default read permission

    const hasManage = roleData.cluster?.includes("manage") ||
                      roleData.cluster?.includes("all") ||
                      roleData.applications?.some(
                        (app) => app.privileges.includes("manage") || app.privileges.includes("all")
                      ) || false;

    return {
      id: roleName,
      name: roleName,
      analysis: hasAnalysis,
      index: hasIndex,
      search: hasSearch,
      manage: hasManage,
      inUse,
    };
  });
}

// Query Keys
export const userKeys = {
  all: ["users"] as const,
  list: () => [...userKeys.all, "list"] as const,
  detail: (username: string) => [...userKeys.all, "detail", username] as const,
};

export const roleKeys = {
  all: ["roles"] as const,
  list: () => [...roleKeys.all, "list"] as const,
  detail: (id: string) => [...roleKeys.all, "detail", id] as const,
};

// Hooks for Users

export function useUsers() {
  return useQuery({
    queryKey: userKeys.list(),
    queryFn: async () => {
      const response = await apiClient.get<ElasticsearchUserResponse>("/_security/user/*");
      return transformUsers(response.data);
    },
    staleTime: 30000, // 30 seconds
  });
}

export function useCreateUser() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (data: CreateUserRequest): Promise<CreateUserResponse> => {
      const response = await apiClient.post<CreateUserResponse>("/_security/user", {
        username: data.username,
        email: data.email,
        roles: [data.role],
      });
      return response.data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: userKeys.list() });
      queryClient.invalidateQueries({ queryKey: roleKeys.list() });
    },
  });
}

export function useUpdateUser() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (data: UpdateUserRequest) => {
      const response = await apiClient.put(`/_security/user/${data.username}`, {
        email: data.email,
        roles: data.role ? [data.role] : undefined,
      });
      return response.data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: userKeys.list() });
      queryClient.invalidateQueries({ queryKey: roleKeys.list() });
    },
  });
}

export function useDeleteUser() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (username: string) => {
      const response = await apiClient.delete(`/_security/user/${username}`);
      return response.data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: userKeys.list() });
      queryClient.invalidateQueries({ queryKey: roleKeys.list() });
    },
  });
}

export function useDeleteUsers() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (usernames: string[]) => {
      await Promise.all(
        usernames.map((username) => apiClient.delete(`/_security/user/${username}`))
      );
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: userKeys.list() });
      queryClient.invalidateQueries({ queryKey: roleKeys.list() });
    },
  });
}

export function useResetPassword() {
  return useMutation({
    mutationFn: async (username: string): Promise<ResetPasswordResponse> => {
      const response = await apiClient.post<ResetPasswordResponse>(
        `/_security/user/${username}/_password/reset`
      );
      return response.data;
    },
  });
}

// Hooks for Roles

export function useRoles() {
  return useQuery({
    queryKey: roleKeys.list(),
    queryFn: async () => {
      const [rolesResponse, usersResponse] = await Promise.all([
        apiClient.get<ElasticsearchRoleResponse>("/_security/role/*"),
        apiClient.get<ElasticsearchUserResponse>("/_security/user/*"),
      ]);

      // Transform users first to check role usage
      const users: User[] = Object.entries(usersResponse.data).map(([username, userData]) => ({
        id: username,
        username: userData.username || username,
        email: userData.email || "",
        role: userData.roles?.[0] || "",
        roles: userData.roles || [],
      }));

      return transformRoles(rolesResponse.data, users);
    },
    staleTime: 30000,
  });
}

export function useCreateRole() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (data: CreateRoleRequest) => {
      // Transform our role format to Elasticsearch format
      const esRole = {
        cluster: data.manage ? ["manage", "monitor"] : ["monitor"],
        indices: [
          {
            names: ["*"],
            privileges: [
              ...(data.search ? ["read"] : []),
              ...(data.index ? ["write", "create_index"] : []),
            ],
          },
        ],
        applications: [
          {
            application: "dsearch",
            privileges: [
              ...(data.analysis ? ["analysis"] : []),
              ...(data.manage ? ["manage"] : []),
            ],
            resources: ["*"],
          },
        ],
      };

      const response = await apiClient.put(`/_security/role/${data.name}`, esRole);
      return response.data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: roleKeys.list() });
    },
  });
}

export function useUpdateRole() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (data: UpdateRoleRequest) => {
      const esRole = {
        cluster: data.manage ? ["manage", "monitor"] : ["monitor"],
        indices: [
          {
            names: ["*"],
            privileges: [
              ...(data.search ? ["read"] : []),
              ...(data.index ? ["write", "create_index"] : []),
            ],
          },
        ],
        applications: [
          {
            application: "dsearch",
            privileges: [
              ...(data.analysis ? ["analysis"] : []),
              ...(data.manage ? ["manage"] : []),
            ],
            resources: ["*"],
          },
        ],
      };

      const response = await apiClient.put(`/_security/role/${data.id}`, esRole);
      return response.data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: roleKeys.list() });
    },
  });
}

export function useDeleteRole() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (roleName: string) => {
      const response = await apiClient.delete(`/_security/role/${roleName}`);
      return response.data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: roleKeys.list() });
    },
  });
}

export function useDeleteRoles() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (roleNames: string[]) => {
      await Promise.all(
        roleNames.map((roleName) => apiClient.delete(`/_security/role/${roleName}`))
      );
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: roleKeys.list() });
    },
  });
}

