"use client";

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import apiClient from "@/lib/api/client";
import type { Collection, CollectionHistory, PaginatedResponse } from "@/types";

// ========================================
// Query Keys
// ========================================

export const collectionKeys = {
  all: ["collections"] as const,
  lists: () => [...collectionKeys.all, "list"] as const,
  list: (filters: Record<string, unknown>) =>
    [...collectionKeys.lists(), filters] as const,
  details: () => [...collectionKeys.all, "detail"] as const,
  detail: (id: string) => [...collectionKeys.details(), id] as const,
  histories: () => [...collectionKeys.all, "history"] as const,
  history: (id: string, filters?: Record<string, unknown>) =>
    [...collectionKeys.histories(), id, filters] as const,
};

// ========================================
// API Functions
// ========================================

async function fetchCollections(): Promise<Collection[]> {
  const response = await apiClient.get("/_dsearch/collection/*");
  return response.data;
}

async function fetchCollection(id: string): Promise<Collection> {
  const response = await apiClient.get(`/_dsearch/collection/${id}`);
  return response.data;
}

async function fetchCollectionHistory(
  id: string,
  params?: { page?: number; pageSize?: number; type?: string }
): Promise<PaginatedResponse<CollectionHistory>> {
  const response = await apiClient.get(`/_dsearch/collection/${id}/history`, {
    params,
  });
  return response.data;
}

interface CreateCollectionData {
  name: string;
  baseId: string;
  template?: string;
  description?: string;
}

async function createCollection(data: CreateCollectionData): Promise<Collection> {
  const response = await apiClient.post("/_dsearch/collection", data);
  return response.data;
}

interface UpdateCollectionData {
  id: string;
  name?: string;
  description?: string;
  sourceConfig?: string;
  schedule?: string;
  autoRun?: boolean;
}

async function updateCollection(data: UpdateCollectionData): Promise<Collection> {
  const { id, ...updateData } = data;
  const response = await apiClient.put(`/_dsearch/collection/${id}`, updateData);
  return response.data;
}

async function deleteCollection(id: string): Promise<void> {
  await apiClient.delete(`/_dsearch/collection/${id}`);
}

type RunType = "full" | "expose" | "continuous";

async function runCollection(id: string, type: RunType): Promise<void> {
  await apiClient.post(`/_dsearch/collection/${id}/run`, { type });
}

async function deleteCollectionHistory(
  collectionId: string,
  historyId: string
): Promise<void> {
  await apiClient.delete(
    `/_dsearch/collection/${collectionId}/history/${historyId}`
  );
}

// ========================================
// Query Hooks
// ========================================

export function useCollections() {
  return useQuery({
    queryKey: collectionKeys.lists(),
    queryFn: fetchCollections,
  });
}

export function useCollection(id: string) {
  return useQuery({
    queryKey: collectionKeys.detail(id),
    queryFn: () => fetchCollection(id),
    enabled: !!id,
  });
}

export function useCollectionHistory(
  id: string,
  params?: { page?: number; pageSize?: number; type?: string }
) {
  return useQuery({
    queryKey: collectionKeys.history(id, params),
    queryFn: () => fetchCollectionHistory(id, params),
    enabled: !!id,
  });
}

// ========================================
// Mutation Hooks
// ========================================

export function useCreateCollection() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: createCollection,
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: collectionKeys.lists() });
    },
  });
}

export function useUpdateCollection() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: updateCollection,
    onSuccess: (data) => {
      queryClient.invalidateQueries({ queryKey: collectionKeys.lists() });
      queryClient.invalidateQueries({
        queryKey: collectionKeys.detail(data.id),
      });
    },
  });
}

export function useDeleteCollection() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: deleteCollection,
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: collectionKeys.lists() });
    },
  });
}

export function useRunCollection() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: ({ id, type }: { id: string; type: RunType }) =>
      runCollection(id, type),
    onSuccess: (_, { id }) => {
      queryClient.invalidateQueries({ queryKey: collectionKeys.detail(id) });
      queryClient.invalidateQueries({ queryKey: collectionKeys.history(id) });
    },
  });
}

export function useDeleteCollectionHistory() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: ({
      collectionId,
      historyId,
    }: {
      collectionId: string;
      historyId: string;
    }) => deleteCollectionHistory(collectionId, historyId),
    onSuccess: (_, { collectionId }) => {
      queryClient.invalidateQueries({
        queryKey: collectionKeys.history(collectionId),
      });
    },
  });
}

