    13→
    14→export function ClusterList() {
    15→  const [searchQuery, setSearchQuery] = useState('');
    16→  const [dialogOpen, setDialogOpen] = useState(false);
    17→  const [editingCluster, setEditingCluster] = useState<Cluster | null>(null);
    18→
    19→  const { data: clusters = [], isLoading, refetch, isRefetching } = useClusters();
    20→  const deleteCluster = useDeleteCluster();
    21→
    22→  // Filter clusters based on search
    23→  const filteredClusters = clusters.filter(
    24→    (cluster) =>
    25→      cluster.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
    26→      cluster.host.toLowerCase().includes(searchQuery.toLowerCase())
    27→  );
    28→
