'use client';

import { useState } from 'react';
import { ClusterCard } from './cluster-card';
import { AddClusterDialog } from './add-cluster-dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Skeleton } from '@/components/ui/skeleton';
import { useClusters, useDeleteCluster } from '@/hooks/use-cluster';
import { Plus, Search, RefreshCw, Server } from 'lucide-react';
import type { Cluster } from '@/types';
import { toast } from 'sonner';

export function ClusterList() {
  const [searchQuery, setSearchQuery] = useState('');
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editingCluster, setEditingCluster] = useState<Cluster | null>(null);

  const { data: clusters = [], isLoading, refetch, isRefetching } = useClusters();
  const deleteCluster = useDeleteCluster();

  // Filter clusters based on search
  const filteredClusters = clusters.filter(
    (cluster) =>
      cluster.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      cluster.host.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const handleAddCluster = () => {
    setEditingCluster(null);
    setDialogOpen(true);
  };

  const handleEditCluster = (cluster: Cluster) => {
    setEditingCluster(cluster);
    setDialogOpen(true);
  };

  const handleDeleteCluster = async (cluster: Cluster, includeData: boolean = false) => {
    try {
      await deleteCluster.mutateAsync({ id: cluster.id, includeData });
      toast.success(`${cluster.name} 클러스터가 삭제되었습니다.`);
    } catch (error) {
      toast.error('클러스터 삭제에 실패했습니다.');
      console.error('Failed to delete cluster:', error);
    }
  };

  const handleDialogSuccess = () => {
    toast.success(
      editingCluster ? '클러스터가 수정되었습니다.' : '클러스터가 추가되었습니다.'
    );
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-semibold">클러스터</h1>
          <p className="text-muted-foreground">
            Elasticsearch 클러스터를 관리합니다.
          </p>
        </div>
        <Button onClick={handleAddCluster}>
          <Plus className="mr-2 h-4 w-4" />
          클러스터 추가
        </Button>
      </div>

      {/* Search and Refresh */}
      <div className="flex items-center gap-4">
        <div className="relative flex-1 max-w-sm">
          <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
          <Input
            placeholder="클러스터 검색..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="pl-9"
          />
        </div>
        <Button
          variant="outline"
          size="icon"
          onClick={() => refetch()}
          disabled={isRefetching}
        >
          <RefreshCw className={`h-4 w-4 ${isRefetching ? 'animate-spin' : ''}`} />
        </Button>
      </div>

      {/* Cluster Grid */}
      {isLoading ? (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
          {[...Array(4)].map((_, i) => (
            <ClusterCardSkeleton key={i} />
          ))}
        </div>
      ) : filteredClusters.length === 0 ? (
        <EmptyState

